# Examen BenchGo V3 - Évaluation Tier 3 (CE2)

## Exercices de Base

### tache_3a
```javascript
function dernierElement(tableau) {
  if (tableau.length === 0) {
    return undefined;
  }
  return tableau[tableau.length - 1];
}
```

### tache_3b
```javascript
function compterJusqua(n) {
  const resultat = [];
  for (let i = 1; i <= n; i++) {
    resultat.push(i);
  }
  return resultat;
}
```

### tache_3c
```javascript
function remplacerLettre(mot, ancienne, nouvelle) {
  // Utilisation de split et join pour remplacer toutes les occurrences
  return mot.split(ancienne).join(nouvelle);
}
```

### tache_3d
```javascript
function sommeTableau(tableau) {
  if (tableau.length === 0) {
    return 0;
  }
  return tableau.reduce((accumulateur, valeurActuelle) => accumulateur + valeurActuelle, 0);
}
```

### tache_3e
```javascript
function contientA(mot) {
  // Utilisation d'une expression régulière pour une recherche insensible à la casse
  return /a/i.test(mot);
}
```

## Exercices Algorithmiques

### algo_facile_1
```javascript
function validerParentheses(s) {
  let compteur = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      compteur++;
    } else if (s[i] === ')') {
      compteur--;
    }
    // Si le compteur devient négatif, il y a une parenthèse fermante sans ouvrante
    if (compteur < 0) {
      return false;
    }
  }
  // Doit être égal à 0 pour que toutes les parenthèses soient appairées
  return compteur === 0;
}
```

### algo_facile_2
```javascript
function fibonacci(n) {
  if (n <= 0) return 0;
  if (n === 1) return 1;

  let a = 0;
  let b = 1;
  for (let i = 2; i <= n; i++) {
    let temp = a + b;
    a = b;
    b = temp;
  }
  return b;
}
```

### algo_moyen_1
```javascript
function motsUniques(s) {
  // On nettoie les espaces superflus et on sépare par n'importe quel caractère de whitespace
  const mots = s.trim().split(/\s+/);

  // Si la chaîne était vide, split peut retourner [''], on filtre pour éviter cela
  const motsFiltrés = mots.filter(mot => mot !== "");

  if (motsFiltrés.length === 0) {
    return 0;
  }

  // Utilisation de Set pour obtenir les éléments uniques
  const ensembleUnique = new Set(motsFiltrés);
  return ensembleUnique.size;
}
```

### algo_difficile_1
```javascript
function aplatirTableau(tab) {
  // On utilise concat avec le spread operator pour aplatir d'un seul niveau
  return [].concat(...tab);
}
```

### algo_defi
```javascript
function rotationDroite(tab, k) {
  if (tab.length === 0) return tab;

  // Gestion du cas où k est supérieur à la longueur du tableau
  const n = tab.length;
  const rotationsReelles = k % n;

  if (rotationsReelles === 0) return [...tab];

  // On coupe le tableau en deux parties : la fin qui va passer devant, et le début
  const partieFin = tab.slice(n - rotationsReelles);
  const partieDebut = tab.slice(0, n - rotationsReelles);

  return partieFin.concat(partieDebut);
}
```

