/**
 * Crée une structure de données Arbre Binaire de Recherche (BST).
 * @returns {Object} - Un objet contenant les méthodes insert et contains.
 */
function creerBST() {
  class Node {
    constructor(val) {
      this.val = val;
      this.left = null;
      this.right = null;
    }
  }

  let root = null;

  return {
    /**
     * Insère une valeur dans l'arbre.
     * @param {*} val - La valeur à insérer.
     */
    insert: function(val) {
      const newNode = new Node(val);
      if (root === null) {
        root = newNode;
        return;
      }

      let current = root;
      while (true) {
        if (val < current.val) {
          if (current.left === null) {
            current.left = newNode;
            break;
          }
          current = current.left;
        } else if (val > current.val) {
          if (current.right === null) {
            current.right = newNode;
            break;
          }
          current = current.right;
        } else {
          // Valeur déjà présente, on ne fait rien pour un BST simple
          break;
        }
      }
    },

    /**
     * Vérifie si une valeur existe dans l'arbre.
     * @param {*} val - La valeur à chercher.
     * @returns {boolean} - True si trouvé.
     */
    contains: function(val) {
      let current = root;
      while (current !== null) {
        if (val === current.val) return true;
        if (val < current.val) {
          current = current.left;
        } else {
          current = current.right;
        }
      }
      return false;
    }
  };
}

