/**
 * Transforme une fonction multi-arguments en une version curried.
 * L'exécution est automatique dès que le nombre d'arguments requis est atteint.
 * @param {Function} fn - La fonction originale.
 * @returns {Function} - La version curried de la fonction.
 */
function curry(fn) {
  return function curried(...args) {
    // Si le nombre d'arguments accumulés est suffisant pour la fonction d'origine
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    } else {
      // Sinon, on retourne une nouvelle fonction qui attend les arguments suivants
      return function(...nextArgs) {
        return curried.apply(this, args.concat(nextArgs));
      };
    }
  };
}

// Tests de validation
const add = curry((a, b, c) => a + b + c);
console.log(add(1)(2)(3)); // 6
console.log(add(1, 2)(3)); // 6

/**
 * Vérifie l'égalité profonde entre deux valeurs (primitives, objets, tableaux).
 * @param {*} a - Première valeur.
 * @param {*} b - Deuxième valeur.
 * @returns {boolean} - True si les structures sont identiques.
 */
function egalProfond(a, b) {
  // Vérification stricte pour primitives et références identiques
  if (a === b) return true;

  // Si l'un des deux n'est pas un objet ou est null, ils ne sont pas égaux
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return false;
  }

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  // Vérification du nombre de propriétés
  if (keysA.length !== keysB.length) return false;

  // Récursion sur chaque propriété
  for (let key of keysA) {
    if (!keysB.includes(key) || !egalProfond(a[key], b[key])) {
      return false;
    }
  }

  return true;
}

