function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
  let failures = 0;
  let lastFailureTime = null;

  return async function(...args) {
    if (state === 'OPEN') {
      if (Date.now() - lastFailureTime >= delaiResetMs) {
        state = 'HALF_OPEN';
      } else {
        throw new Error("Circuit Breaker is OPEN");
      }
