function remplirMatrice(grille, x, y, nouvelleValeur) {
  const targetValue = grille[y][x];

  // If the cell value already equals nouvelleValeur, do nothing and return unchanged
  if (targetValue === undefined || targetValue === nouvelleValeur) {
    return grille;
